    "stem": "A 59-year-old man attends the specialist medical outpatient clinic at Sheikh Shakhbout Medical City Abu Dhabi with clinical findings indicative of Acute Severe Asthma Exacerbation in Adult. Clinical examination and investigative review confirm nebulized salbutamol and ipratropium, systemic oral prednisolone, and supplemental oxygen. Vitals reveal blood pressure of 122/72 mm Hg, heart rate of 72/min, respiratory rate of 14/min, and temperature of 38.0C (98.5F). Diagnostic serum testing, focused physiological assessment, and targeted structural evaluations demonstrate characteristic pathophysiological hallmarks of acute severe asthma exacerbation in adult. Which of the following is the most appropriate next step in clinical management according to Department of Health Abu Dhabi / DHA clinical practice guidelines?",
    "options": [
      {
        "text": "Oral broad-spectrum fluoroquinolone monotherapy without microbiological confirmation",
        "correct": false,
        "explanation": "Incorrect: Empiric fluoroquinolones risk severe adverse effects including tendonopathy and select for multidrug-resistant pathogens when unindicated."
      },
      {
        "text": "Nebulized salbutamol and ipratropium, systemic oral prednisolone, and supplemental oxygen",
        "correct": true,
        "explanation": "Correct: According to established evidence-based consensus and clinical practice guidelines, the primary indicated management for this clinical scenario is nebulized salbutamol and ipratropium, systemic oral prednisolone, and supplemental oxygen. This directly addresses the underlying pathophysiological abnormality, optimizes therapeutic outcomes, and mitigates disease-specific morbidity."
      },
      {
        "text": "Oral bisphosphonate administration during active hypocalcemia",
        "correct": false,
        "explanation": "Incorrect: Potent osteoclast inhibition in hypocalcemic states triggers life-threatening cardiac arrhythmias, tetany, and laryngeal spasm."
      },
      {
        "text": "Intensive intravenous insulin bolus therapy without baseline potassium evaluation",
        "correct": false,
        "explanation": "Incorrect: Rapid insulin infusion shifts extracellular potassium intracellularly, precipitating lethal hypokalemia-induced cardiac arrest."
      },
      {
        "text": "Diagnostic lumbar puncture prior to excluding intracranial mass effect with neuroimaging",
        "correct": false,
        "explanation": "Incorrect: Performing dural puncture in the presence of focal space-occupying lesions risks fatal transtentorial or tonsillar herniation."
      }
    ],
