    "stem": "A 24-year-old man attends the specialist medical outpatient clinic at Sheikh Shakhbout Medical City Abu Dhabi with clinical findings indicative of Nephrotic Syndrome Adult Minimal Change Disease. Clinical examination and investigative review confirm oral high-dose prednisolone therapy for 8 to 16 weeks and loop diuretics for edema. Vitals reveal blood pressure of 121/77 mm Hg, heart rate of 93/min, respiratory rate of 19/min, and temperature of 38.3C (98.8F). Diagnostic serum testing, focused physiological assessment, and targeted structural evaluations demonstrate characteristic pathophysiological hallmarks of nephrotic syndrome adult minimal change disease. Which of the following is the most appropriate next step in clinical management according to Department of Health Abu Dhabi / DHA clinical practice guidelines?",
